CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- 1. Insert into auth.users first to satisfy foreign key constraints
ON CONFLICT (id) DO NOTHING;

-- 2. Insert into public.profiles (Using ON CONFLICT DO UPDATE in case auth trigger fired)
ON CONFLICT (id) DO UPDATE SET full_name=EXCLUDED.full_name, role=EXCLUDED.role, department=EXCLUDED.department;

-- 3. Insert Research Entries
ON CONFLICT (id) DO NOTHING;
